/**
 * Calculate the Levenshtein distance between two strings.
 * @param {string} a - First string
 * @param {string} b - Second string
 * @returns {number} The edit distance between a and b
 */
function levenshteinDistance(a, b) {
  const m = a.length;
  const n = b.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Initialize base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,      // deletion
        dp[i][j - 1] + 1,      // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Find the closest matching property name using Levenshtein distance.
 * Only returns a suggestion if the distance is <= 3.
 * If multiple properties tie, returns the alphabetically first one.
 * 
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} candidateProperties - List of available property names
 * @returns {string|null} The closest matching property or null
 */
function findClosestMatch(missingProperty, candidateProperties) {
  let bestMatch = null;
  let bestDistance = Infinity;

  for (const candidate of candidateProperties) {
    const distance = levenshteinDistance(missingProperty, candidate);

    if (distance <= 3) {
      if (distance < bestDistance || 
          (distance === bestDistance && (bestMatch === null || candidate < bestMatch))) {
        bestMatch = candidate;
        bestDistance = distance;
      }
    }
  }

  return bestMatch;
}

/**
 * Diagnose a missing property in a KnockoutJS binding context.
 * 
 * @param {string} propertyName - The name of the property that failed to bind
 * @param {object} viewModel - The KnockoutJS-style ViewModel object
 * @returns {object} An error diagnosis object
 */
function diagnoseMissingProperty(propertyName, viewModel) {
  const availableProperties = Object.keys(viewModel).sort();
  const suggestion = findClosestMatch(propertyName, availableProperties);

  return {
    error: true,
    missingProperty: propertyName,
    availableProperties: availableProperties,
    suggestion: suggestion
  };
}

/**
 * Factory to create a debugging helper for a specific ViewModel.
 * 
 * @param {object} viewModel - The KnockoutJS-style ViewModel object
 * @returns {object} A debug helper object with diagnose method
 */
function createDebugHelper(viewModel) {
  return {
    /**
     * Diagnose a missing property.
     * @param {string} propertyName - Property name that failed
     * @returns {object} Error diagnosis object
     */
    diagnose: function(propertyName) {
      return diagnoseMissingProperty(propertyName, viewModel);
    }
  };
}

module.exports = {
  createDebugHelper: createDebugHelper,
  diagnoseMissingProperty: diagnoseMissingProperty,
  levenshteinDistance: levenshteinDistance
};"}

