/**
 * Test script for KnockoutJS Template Binding Error Debugger
 */

const koDebug = require('./ko-debug.js');

// Sample ViewModel with required properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: true,
  totalCount: 0
};

// Create debug helper
const debugHelper = koDebug.createDebugHelper(sampleViewModel);

let allPassed = true;

function runTest(testName, actual, expected) {
  const passed = JSON.stringify(actual) === JSON.stringify(expected);

  if (passed) {
    console.log(`PASS: ${testName}`);
  } else {
    console.log(`FAIL: ${testName}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
    allPassed = false;
  }
}

// Test 1: Diagnose missing property "item" (should suggest "items", distance 1)
const test1 = debugHelper.diagnose('item');
runTest(
  'Test 1: diagnose "item" should suggest "items"',
  test1,
  {
    error: true,
    missingProperty: 'item',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'items'
  }
);

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem", distance 2)
const test2 = debugHelper.diagnose('selctedItem');
runTest(
  'Test 2: diagnose "selctedItem" should suggest "selectedItem"',
  test2,
  {
    error: true,
    missingProperty: 'selctedItem',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'selectedItem'
  }
);

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
const test3 = debugHelper.diagnose('completelyWrong');
runTest(
  'Test 3: diagnose "completelyWrong" should have null suggestion',
  test3,
  {
    error: true,
    missingProperty: 'completelyWrong',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: null
  }
);

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading", distance 3)
const test4 = debugHelper.diagnose('isLoad');
runTest(
  'Test 4: diagnose "isLoad" should suggest "isLoading"',
  test4,
  {
    error: true,
    missingProperty: 'isLoad',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'isLoading'
  }
);

// Test 5: Verify availableProperties are sorted
const test5 = debugHelper.diagnose('nonexistent');
const sorted = test5.availableProperties.join(',') === test5.availableProperties.slice().sort().join(',');
if (sorted) {
  console.log('PASS: Test 5: availableProperties are sorted alphabetically');
} else {
  console.log('FAIL: Test 5: availableProperties are not sorted');
  allPassed = false;
}

// Test 6: Verify Levienshtein distance calculation
const dist = koDebug.levenshteinDistance('kitten', 'sitting');
if (dist === 3) {
  console.log('PASS: Test 6: Levenshtein distance kitten->sitting = 3');
} else {
  console.log(`FAIL: Test 6: Expected 3, got ${dist}`);
  allPassed = false;
}

// Summary
console.log('');
if (allPassed) {
  console.log('All tests PASSED!');
  process.exit(0);
} else {
  console.log('Some tests FAILED!');
  process.exit(1);
}
